// Simplified, connected 7‑segment display block with overall envelope [12.7, 19, 8.2]
// Fix: semantic mismatch -> adds 7 distinct segment bars in standard layout.
// Fix: connectivity -> all translate() values are formula-based and include slight overlap.
// Result: single connected solid, recognizable 7-segment silhouette.

$fn = 48;

// Overall envelope (requested)
body_W = 12.7;
body_H = 19;
body_D = 8.2;

// Connection overlap (1–2mm)
overlap = 1.2;

// Bezel / face
bezel_margin = 1.0;
bezel_thickness = 0.8;

// Segment geometry (raised bars on the face)
segment_inset_margin = 2.0;     // keeps segments away from bezel
segment_raise = 0.8;            // how far segments protrude from face
segment_th = 1.6;               // segment bar thickness (in XY plane)
segment_gap = 1.2;              // gap between top/middle/bottom and verticals

// Decimal point (kept simple, connected)
decimal_r = 0.9;
decimal_h = 0.8;

// Leads (kept simple, connected)
lead_count = 10;
lead_pitch = 2.54;
lead_W = 0.6;
lead_T = 0.5;
lead_L = 6.0;
lead_bar_T = 0.8;

// Mount bosses (kept simple, connected)
mount_boss_r = 1.2;
mount_boss_h = 1.2;

// ---------- Base Shapes ----------
module display_body() {
  cube([body_W, body_H, body_D], center=true);
}

module front_bezel_outer() {
  // Touches body front with overlap
  translate([0, 0, body_D/2 + bezel_thickness/2 - overlap])
    cube([body_W, body_H, bezel_thickness], center=true);
}

module front_bezel_inner_cut() {
  // Cut window through bezel only (slightly deeper for clean boolean)
  translate([0, 0, body_D/2 + bezel_thickness/2 - overlap])
    cube([body_W - 2*bezel_margin, body_H - 2*bezel_margin, bezel_thickness + 2*overlap], center=true);
}

module front_bezel_detail() {
  difference() {
    front_bezel_outer();
    front_bezel_inner_cut();
  }
}

// ---------- 7-Segment Bars (raised, connected to bezel) ----------
module seg_bar_h(len, th, h) cube([len, th, h], center=true);
module seg_bar_v(th, len, h) cube([th, len, h], center=true);

module seven_segments() {
  // Available inner window for segments
  inner_W = body_W - 2*segment_inset_margin;
  inner_H = body_H - 2*segment_inset_margin;

  // Segment lengths (simple proportions)
  hlen = max(1, inner_W - 2*segment_th);
  vlen = max(1, (inner_H - 3*segment_th - 2*segment_gap)/2);

  // Z placement: sit on bezel front with overlap so it's one solid
  z_seg = body_D/2 + segment_raise/2 - overlap;

  // Y positions for top/middle/bottom
  y_top =  inner_H/2 - segment_th/2;
  y_mid =  0;
  y_bot = -inner_H/2 + segment_th/2;

  // X positions for left/right verticals
  x_left  = -inner_W/2 + segment_th/2;
  x_right =  inner_W/2 - segment_th/2;

  // Y centers for upper/lower verticals
  y_upper =  (segment_th + segment_gap)/2 + vlen/2;
  y_lower = -(segment_th + segment_gap)/2 - vlen/2;

  union() {
    // a (top)
    translate([0, y_top, z_seg]) seg_bar_h(hlen, segment_th, segment_raise);
    // g (middle)
    translate([0, y_mid, z_seg]) seg_bar_h(hlen, segment_th, segment_raise);
    // d (bottom)
    translate([0, y_bot, z_seg]) seg_bar_h(hlen, segment_th, segment_raise);

    // f (upper-left)
    translate([x_left,  y_upper, z_seg]) seg_bar_v(segment_th, vlen, segment_raise);
    // b (upper-right)
    translate([x_right, y_upper, z_seg]) seg_bar_v(segment_th, vlen, segment_raise);

    // e (lower-left)
    translate([x_left,  y_lower, z_seg]) seg_bar_v(segment_th, vlen, segment_raise);
    // c (lower-right)
    translate([x_right, y_lower, z_seg]) seg_bar_v(segment_th, vlen, segment_raise);
  }
}

module decimal_point() {
  // Place on lower-right of inner window; connect to bezel with overlap
  inner_W = body_W - 2*segment_inset_margin;
  inner_H = body_H - 2*segment_inset_margin;

  z_dp = body_D/2 + decimal_h/2 - overlap;
  x_dp =  inner_W/2 - decimal_r;
  y_dp = -inner_H/2 + decimal_r;

  translate([x_dp, y_dp, z_dp])
    cylinder(r=decimal_r, h=decimal_h, center=true);
}

// ---------- Leads / Mounting (connected) ----------
module pin_leads_bar() {
  // Bar touches body bottom with overlap
  translate([0,
             -body_H/2 - lead_L/2 + overlap,
             -body_D/2 + lead_bar_T/2 - overlap])
    cube([lead_pitch*(lead_count-1) + lead_W, lead_L, lead_bar_T], center=true);
}

module pin_leads_comb() {
  // Thin comb plate coincident with bar (connected)
  translate([0,
             -body_H/2 - lead_L/2 + overlap,
             -body_D/2 + lead_T/2 - overlap])
    cube([lead_pitch*(lead_count-1) + lead_W, lead_L, lead_T], center=true);
}

module pin_leads() {
  union() {
    pin_leads_bar();
    pin_leads_comb();
  }
}

module mount_boss_left() {
  // Touches body bottom with overlap
  translate([-body_W/2 + mount_boss_r + bezel_margin,
             0,
             -body_D/2 - mount_boss_h/2 + overlap])
    cylinder(r=mount_boss_r, h=mount_boss_h, center=true);
}

module mount_boss_right() {
  translate([ body_W/2 - mount_boss_r - bezel_margin,
              0,
             -body_D/2 - mount_boss_h/2 + overlap])
    cylinder(r=mount_boss_r, h=mount_boss_h, center=true);
}

module mounting_features() {
  union() {
    mount_boss_left();
    mount_boss_right();
  }
}

// ---------- Final Model (single connected solid) ----------
module complete_model() {
  union() {
    display_body();
    front_bezel_detail();
    seven_segments();
    decimal_point();
    pin_leads();
    mounting_features();
  }
}

complete_model();

// Parameters
mast_h = 300; //[150:600:1]
mast_d = 8; //[4:16:0.5]
base_d = 40; //[20:80:1]
base_h = 12; //[6:24:1]
flange_d = 55; //[30:110:1]
flange_h = 4; //[2:10:0.5]
hole_count = 3; //[2:8:1]
hole_d = 4.2; //[2.5:8:0.1]
hole_circle_d = 45; //[25:90:1]
tip_cap_h = 10; //[5:25:1]
tip_cap_d = 10; //[6:20:0.5]
cable_hole_d = 6; //[3:12:0.5]
cable_hole_offset = 10; //[0:25:1]
rib_count = 12; //[6:24:1]
rib_depth = 1.2; //[0.5:3:0.1]
rib_width = 3; //[1:6:0.5]
rib_h = 10; //[4:20:1]
overlap = 1; //[0.5:2:0.1]

// Base Shapes
module flange_cyl() {
  translate([0, 0, flange_h/2])
    cylinder(r=flange_d/2, h=flange_h, center=true);
}

module base_cyl() {
  translate([0, 0, flange_h + base_h/2 - overlap])
    cylinder(r=base_d/2, h=base_h, center=true);
}

module mast_cyl() {
  translate([0, 0, flange_h + base_h - overlap + mast_h/2 - overlap])
    cylinder(r=mast_d/2, h=mast_h, center=true);
}

module tip_cap_sphere() {
  translate([0, 0, flange_h + base_h - overlap + mast_h - overlap + tip_cap_h/2])
    sphere(r=tip_cap_d/2, center=true);
}

module tip_cap_cyl() {
  translate([0, 0, flange_h + base_h - overlap + mast_h - overlap + tip_cap_h/2])
    cylinder(r=tip_cap_d/2, h=tip_cap_h, center=true);
}

module mount_hole(pos) {
  translate(pos)
    cylinder(r=hole_d/2, h=flange_h + base_h + overlap*2, center=true);
}

module cable_exit_hole() {
  translate([cable_hole_offset, 0, (flange_h + base_h)/2])
    cylinder(r=cable_hole_d/2, h=flange_h + base_h + overlap*2, center=true);
}

module rib(pos, rot) {
  translate(pos)
  rotate([0, 0, rot])
    cube([rib_depth, rib_width, rib_h], center=true);
}

// Operations
module tip_cap_union() {
  union() {
    tip_cap_cyl();
    tip_cap_sphere();
  }
}

module antenna_solid_union() {
  union() {
    flange_cyl();
    base_cyl();
    mast_cyl();
    tip_cap_union();
    for (i = [0:rib_count-1]) {
      rib([(base_d/2 + rib_depth/2 - overlap)*cos(i*360/rib_count),
           (base_d/2 + rib_depth/2 - overlap)*sin(i*360/rib_count),
           flange_h + rib_h/2 - overlap], i*360/rib_count);
    }
  }
}

module mount_holes_union() {
  union() {
    for (i = [0:hole_count-1]) {
      mount_hole([(hole_circle_d/2)*cos(i*360/hole_count),
                  (hole_circle_d/2)*sin(i*360/hole_count),
                  (flange_h + base_h)/2]);
    }
  }
}

module holes_union_all() {
  union() {
    mount_holes_union();
    cable_exit_hole();
  }
}

// Final Output
difference() {
  antenna_solid_union();
  holes_union_all();
}

// A axial: [3.4, 1.75, 0.3]
// Simple, clearly axial (rotationally symmetric) part:
// - Outer cylinder: length = 3.4, OD = 1.75
// - Central through-bore sized by wall_thickness (0.3) -> ID = OD - 2*wall
// - Small end chamfers for a clean silhouette
// All geometry is a single connected solid; no floating parts.

$fn = 96;

// Parameters (match request)
body_length     = 3.4;   // axial length
body_od         = 1.75;  // outer diameter
wall_thickness  = 0.3;   // radial wall thickness (sets bore)

// Derived
body_r  = body_od/2;
body_id = max(0.01, body_od - 2*wall_thickness);
bore_r  = body_id/2;

// Small, proportional chamfer (kept simple)
chamfer_len = min(0.25, body_length*0.12);
eps = 0.02; // slight overlap for robust booleans

module axial_part() {
  difference() {
    // Outer body with simple end chamfers (still rotationally symmetric)
    union() {
      // Main straight section
      cylinder(h = body_length - 2*chamfer_len, r = body_r, center = true);

      // Top chamfer frustum
      translate([0,0,(body_length/2 - chamfer_len/2)])
        cylinder(h = chamfer_len + eps, r1 = body_r, r2 = max(0.01, body_r - chamfer_len), center = true);

      // Bottom chamfer frustum
      translate([0,0,(-body_length/2 + chamfer_len/2)])
        cylinder(h = chamfer_len + eps, r1 = max(0.01, body_r - chamfer_len), r2 = body_r, center = true);
    }

    // Central through-bore (axial feature)
    cylinder(h = body_length + 2*eps, r = bore_r, center = true);
  }
}

axial_part();

// Parameters
axial_x = 5.21; //[2.605:10.42:0.01]
axial_y = 2.72; //[1.36:5.44:0.01]
axial_z = 0;    //[−5:5:0.01]

line_diameter = 0.5; //[0.25:1:0.05]
endpoint_marker_diameter = 1.5; //[0.75:3:0.05]
endpoint_marker_height = 1; //[0.5:2:0.05]
origin_marker_diameter = 1.5; //[0.75:3:0.05]
origin_marker_height = 1; //[0.5:2:0.05]
arrowhead_length = 1.2; //[0.6:2.4:0.05]
arrowhead_diameter = 1.6; //[0.8:3.2:0.05]

// Overlap for solid connections (1–2mm requested)
connect_overlap = 1.2; //[0.2:2:0.05]

// Calculate the length of the axial vector
axial_length = sqrt(axial_x*axial_x + axial_y*axial_y + axial_z*axial_z);

// Helper: rotate Z so a cylinder aligned with +Z points along the axial vector in XY plane
function axial_angle_deg(x,y) = atan2(y, x);

// Axial reference indicator (single connected, clearly axial/axisymmetric)
module axial_reference_indicator() {
  // Derived sizes/positions to guarantee contact
  r_line = line_diameter/2;
  r_origin = origin_marker_diameter/2;
  r_end = endpoint_marker_diameter/2;

  // Make the "shaft" run from origin to endpoint with slight extension into both end features
  shaft_len = axial_length + 2*connect_overlap;

  // Place origin marker so its top face overlaps the shaft start
  // (origin marker centered at z = origin_h/2, shaft centered at z = shaft_len/2)
  origin_z = origin_marker_height/2;

  // Place endpoint marker so its bottom face overlaps the shaft end
  end_z = axial_length - endpoint_marker_height/2;

  // Place arrowhead so its base overlaps the endpoint marker/shaft region
  // (arrowhead centered so its base is slightly inside the endpoint marker)
  arrow_z = axial_length + arrowhead_length/2 - connect_overlap;

  union() {
    // Main axial shaft (axisymmetric, single body backbone)
    rotate([0, 90, axial_angle_deg(axial_x, axial_y)])
      translate([0, 0, axial_length/2])
        cylinder(h=shaft_len, r=r_line, center=true, $fn=48);

    // Origin marker (coaxial with shaft)
    rotate([0, 90, axial_angle_deg(axial_x, axial_y)])
      translate([0, 0, origin_z])
        cylinder(h=origin_marker_height, r=r_origin, center=true, $fn=64);

    // Endpoint marker (coaxial with shaft)
    rotate([0, 90, axial_angle_deg(axial_x, axial_y)])
      translate([0, 0, end_z])
        cylinder(h=endpoint_marker_height, r=r_end, center=true, $fn=64);

    // Arrowhead (coaxial with shaft, pointing outward)
    rotate([0, 90, axial_angle_deg(axial_x, axial_y)])
      translate([0, 0, arrow_z])
        cylinder(h=arrowhead_length, r1=arrowhead_diameter/2, r2=0, center=true, $fn=64);
  }
}

// Render the model
axial_reference_indicator();

// Parameters
bore_diameter_mm = 8; //[4:16:0.1]
outer_diameter_mm = 22; //[11:44:0.1]
width_mm = 7; //[3.5:14:0.1]
radial_clearance_mm = 0.3; //[0.1:1:0.05]
outer_ring_radial_thickness_mm = 2.6; //[1.3:5.2:0.1]
inner_ring_radial_thickness_mm = 2.4; //[1.2:4.8:0.1]
shield_thickness_mm = 0.6; //[0.3:1.2:0.05]
shield_radial_overlap_mm = 0.8; //[0.3:2:0.05]
shield_axial_overlap_mm = 0.6; //[0.3:1.5:0.05]
ball_diameter_mm = 3.5; //[2:6:0.1]
ball_count = 7; //[5:12:1]
ball_overlap_mm = 0.8; //[0.3:2:0.05]
fill_annulus_extra_mm = 0.4; //[0.1:1.5:0.05]
connection_overlap_mm = 0.8; //[0.3:2:0.05]

// Ball Bearing - complete geometry
module ball_bearing() {
  color("Silver") {
    // Outer Ring
    difference() {
      cylinder(r=outer_diameter_mm/2, h=width_mm, center=true);
      cylinder(r=outer_diameter_mm/2 - outer_ring_radial_thickness_mm, h=width_mm + 2*connection_overlap_mm, center=true);
    }
    // Inner Ring
    difference() {
      cylinder(r=bore_diameter_mm/2 + inner_ring_radial_thickness_mm, h=width_mm, center=true);
      cylinder(r=bore_diameter_mm/2, h=width_mm + 2*connection_overlap_mm, center=true);
    }
    // Filled Annulus
    difference() {
      cylinder(r=outer_diameter_mm/2 - outer_ring_radial_thickness_mm + fill_annulus_extra_mm, h=width_mm - 2*shield_thickness_mm + 2*shield_axial_overlap_mm, center=true);
      cylinder(r=bore_diameter_mm/2 + inner_ring_radial_thickness_mm - fill_annulus_extra_mm, h=width_mm - 2*shield_thickness_mm + 2*shield_axial_overlap_mm + 2*connection_overlap_mm, center=true);
    }
    // Shields
    union() {
      translate([0, 0, width_mm/2 - shield_thickness_mm/2 - shield_axial_overlap_mm])
        difference() {
          cylinder(r=outer_diameter_mm/2 - outer_ring_radial_thickness_mm + shield_radial_overlap_mm, h=shield_thickness_mm, center=true);
          cylinder(r=bore_diameter_mm/2 + inner_ring_radial_thickness_mm - shield_radial_overlap_mm, h=shield_thickness_mm + 2*connection_overlap_mm, center=true);
        }
      translate([0, 0, -(width_mm/2 - shield_thickness_mm/2 - shield_axial_overlap_mm)])
        difference() {
          cylinder(r=outer_diameter_mm/2 - outer_ring_radial_thickness_mm + shield_radial_overlap_mm, h=shield_thickness_mm, center=true);
          cylinder(r=bore_diameter_mm/2 + inner_ring_radial_thickness_mm - shield_radial_overlap_mm, h=shield_thickness_mm + 2*connection_overlap_mm, center=true);
        }
    }
  }
}

// Bearing Ball - complete geometry
module bearing_ball() {
  color("DimGray") {
    sphere(r=ball_diameter_mm/2, center=true);
  }
}

// Assembly
module assembly() {
  ball_bearing();
  for (i = [0:ball_count-1]) {
    rotate([0, 0, i*360/ball_count])
      translate([((bore_diameter_mm/2 + inner_ring_radial_thickness_mm) + (outer_diameter_mm/2 - outer_ring_radial_thickness_mm))/2, 0, 0])
        bearing_ball();
  }
}

assembly();

