      for (i = [0:set_screw_count-1]) {
        rotate([0, 0, i*360/set_screw_count]) {
          translate([0, 0, -hub_length_mm/2 + set_screw_z_offset_mm])
            rotate([0, 90, 0])
              cylinder(r=set_screw_diameter_mm/2, h=set_screw_length_mm, center=true);
        }
      }
    }
  }
}

